create table if not exists public.notification_preferences(id uuid primary key default gen_random_uuid(),employee_id uuid references employees(id) on delete cascade unique,preferences jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.weather_observations(id uuid primary key default gen_random_uuid(),observed_at timestamptz not null,source text,temperature_f numeric,feels_like_f numeric,humidity numeric,wind_mph numeric,precipitation_in numeric,condition text,raw jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
