create table if not exists public.rentals(id uuid primary key default gen_random_uuid(),customer_name text not null,customer_contact jsonb not null default '{}'::jsonb,rental_type text not null,resource_id uuid,start_at timestamptz not null,end_at timestamptz not null,status text not null default 'inquiry',amount numeric(12,2),deposit numeric(12,2),notes text,created_by uuid,updated_by uuid,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.incident_reports(id uuid primary key default gen_random_uuid(),incident_number bigint generated by default as identity,occurred_at timestamptz not null,location text,incident_type text not null,severity text not null default 'minor',people_involved jsonb not null default '[]'::jsonb,description text not null,actions_taken text,status text not null default 'open',reported_by uuid,reviewed_by uuid,created_by uuid,updated_by uuid,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.attachments(id uuid primary key default gen_random_uuid(),entity_type text not null,entity_id uuid not null,bucket text not null,storage_path text not null,file_name text not null,mime_type text,file_size bigint,uploaded_by uuid,created_at timestamptz not null default now());
