create table if not exists public.activity_feed(id uuid primary key default gen_random_uuid(),entity_type text,entity_id uuid,action text not null,summary text,actor_id uuid,metadata jsonb not null default '{}'::jsonb,created_by uuid,updated_by uuid,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.audit_logs(id uuid primary key default gen_random_uuid(),actor_id uuid,actor_email text,action text not null,entity_type text,entity_id uuid,before_data jsonb,after_data jsonb,ip_address inet,user_agent text,created_at timestamptz not null default now());

create table if not exists public.website_settings(id uuid primary key default gen_random_uuid(),key text unique not null,value jsonb not null default '{}'::jsonb,published_at timestamptz,published_by uuid,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.website_announcements(id uuid primary key default gen_random_uuid(),title text,message text not null,status text not null default 'draft',starts_at timestamptz,ends_at timestamptz,published_at timestamptz,created_by uuid,updated_by uuid,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.content_revisions(id uuid primary key default gen_random_uuid(),content_key text not null,revision integer not null,data jsonb not null,created_by uuid,created_at timestamptz not null default now(),unique(content_key,revision));
create table if not exists public.clover_daily_summaries(id uuid primary key default gen_random_uuid(),business_date date unique not null,gross_sales numeric(12,2),net_sales numeric(12,2),tax numeric(12,2),tips numeric(12,2),refunds numeric(12,2),orders_count integer,raw jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.clover_transactions(id uuid primary key default gen_random_uuid(),external_id text unique not null,occurred_at timestamptz,employee_external_id text,amount numeric(12,2),tip numeric(12,2),tax numeric(12,2),status text,raw jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create table if not exists public.reports(id uuid primary key default gen_random_uuid(),name text not null,report_type text not null,parameters jsonb not null default '{}'::jsonb,result_path text,status text not null default 'queued',generated_by uuid,generated_at timestamptz,created_by uuid,updated_by uuid,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.saved_views(id uuid primary key default gen_random_uuid(),employee_id uuid references employees(id) on delete cascade,module text not null,name text not null,filters jsonb not null default '{}'::jsonb,columns jsonb not null default '[]'::jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.integrations(id uuid primary key default gen_random_uuid(),provider text unique not null,status text not null default 'disconnected',settings jsonb not null default '{}'::jsonb,last_sync_at timestamptz,last_error text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.integration_sync_logs(id uuid primary key default gen_random_uuid(),integration_id uuid references integrations(id) on delete cascade,started_at timestamptz not null default now(),finished_at timestamptz,status text not null default 'running',records_processed integer not null default 0,error text,details jsonb not null default '{}'::jsonb); 
create table if not exists public.export_history(id uuid primary key default gen_random_uuid(),export_type text not null,parameters jsonb not null default '{}'::jsonb,file_path text,status text not null default 'queued',requested_by uuid,completed_at timestamptz,created_at timestamptz not null default now());
create table if not exists public.backup_history(id uuid primary key default gen_random_uuid(),backup_type text not null,status text not null default 'queued',storage_path text,started_at timestamptz not null default now(),completed_at timestamptz,error text,requested_by uuid,created_at timestamptz not null default now());
create table if not exists public.app_settings(id uuid primary key default gen_random_uuid(),key text unique not null,value jsonb not null default '{}'::jsonb,visibility text not null default 'owner',created_at timestamptz not null default now(),updated_at timestamptz not null default now());

-- Consistent update timestamps.
do $$ declare r record; begin for r in select tablename from pg_tables where schemaname='public' and tablename not in ('permissions','role_permissions','shift_breaks','certification_types','inspection_template_items','equipment_meter_logs','inventory_categories','inventory_count_items','purchase_order_items','teams','notification_receipts','weather_alerts','attachments','audit_logs','content_revisions','clover_transactions','integration_sync_logs','export_history','backup_history') loop execute format('drop trigger if exists set_updated_at on public.%I',r.tablename); execute format('create trigger set_updated_at before update on public.%I for each row execute function public.set_updated_at()',r.tablename); end loop; end $$;

-- Service-role-only browser security. Netlify Functions use the service role and enforce app roles.
do $$ declare r record; begin for r in select tablename from pg_tables where schemaname='public' loop execute format('alter table public.%I enable row level security',r.tablename); end loop; end $$;

-- Helpful indexes.
create index if not exists idx_shifts_start on shifts(start_at);
create index if not exists idx_games_start_field on games(start_at,field_id);
create index if not exists idx_inspections_field_created on field_inspections(field_id,created_at desc);
create index if not exists idx_work_orders_status on work_orders(status,priority);
create index if not exists idx_inventory_low on inventory_items(quantity_on_hand,reorder_point);
create index if not exists idx_notifications_status_schedule on notifications(status,scheduled_at);
create index if not exists idx_activity_created on activity_feed(created_at desc);
create index if not exists idx_audit_created on audit_logs(created_at desc);

-- Storage buckets (private by default).
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values
('inspection-photos','inspection-photos',false,15728640,array['image/jpeg','image/png','image/webp']),
('incident-files','incident-files',false,26214400,array['image/jpeg','image/png','image/webp','application/pdf']),
('employee-documents','employee-documents',false,26214400,array['application/pdf','image/jpeg','image/png']),
('report-exports','report-exports',false,52428800,array['application/pdf','text/csv','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'])
on conflict(id) do update set file_size_limit=excluded.file_size_limit,allowed_mime_types=excluded.allowed_mime_types;
